package com.javy.backend.shared.logging;

import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;

import java.io.IOException;

/**
 * Filter responsible for logging request metadata such as HTTP method,
 * request path, query parameters, and correlation ID.
 *
 * <p>
 * The correlation ID is generated by {@link CorrelationIdFilter}
 * and retrieved from the Mapped Diagnostic Context (MDC).
 * </p>
 */
@Component
public class RequestLoggingFilter implements Filter {

    private static final Logger log = LoggerFactory.getLogger(RequestLoggingFilter.class);

    @Override
    public void doFilter(
            ServletRequest request,
            ServletResponse response,
            FilterChain chain
    ) throws IOException, ServletException {

        HttpServletRequest http = (HttpServletRequest) request;

        String correlationId = MDC.get("correlationId");
        String method = http.getMethod();
        String path = http.getRequestURI();
        String query = http.getQueryString();

        log.info(
                "Incoming request [{}]: method={}, path={}, query={}",
                correlationId,
                method,
                path,
                (query != null ? query : "none")
        );

        chain.doFilter(request, response);

        log.info("Completed request [{}]: method={}, path={}", correlationId, method, path);
    }
}